input.function:
async () => {
  const names = ['portrait.png','wide.png','sky.png'];
  const out = {};
  for (const n of names) {
    const img = new Image();
    img.src = '/' + n + '?cb=' + Date.now();
    await img.decode();
    out[n] = [img.naturalWidth, img.naturalHeight];
  }
  return out;
}

